int candidate_x = cursor_x_;
int candidate_y = cursor_y_;
int candidate_row_height = row_height_;
if (outer_width > width_ - candidate_x) {
    candidate_x = 0;
    candidate_y += row_height_;
    candidate_row_height = 0;
}
if (outer_height > height_ - candidate_y)
    return std::nullopt;

auto candidate = shelf_;
const auto placement = candidate.insert(glyph.width, glyph.height);
if (!placement) return std::nullopt;
// padded 생성과 coverage 복사
if (!texture_.write(placement->outer, padded))
    return std::nullopt;
shelf_ = candidate;
return Region{placement->ink, revision_};

std::vector<unsigned char> padded(std::size_t(outer.w)*outer.h, 0);
for (int row=0; row<glyph.height; ++row)
    std::copy_n(glyph.coverage.data()+std::size_t(row)*glyph.width,
                glyph.width,
                padded.data()+std::size_t(row+1)*outer.w+1);
// MaskTexture::write 내부
gl_.TexSubImage2D(Texture2D, 0, r.x, r.y, r.w, r.h,
                  Red, UnsignedByte, bytes.data());

gl_.BindTexture(Texture2D, texture);
gl_.BindBuffer(PixelUnpackBuffer, 0);
gl_.PixelStorei(UnpackAlignment, 1);
gl_.PixelStorei(UnpackRowLength, 0);
gl_.PixelStorei(UnpackSkipRows, 0);
gl_.PixelStorei(UnpackSkipPixels, 0);

const auto r = item.region.ink;
request.rect = {x+item.x, baseline+item.y, float(r.w), float(r.h)};
request.uv = {r.x/w, r.y/h, (r.x+r.w)/w, (r.y+r.h)/h};

if (!ready_ || atlas_->revision()!=revision_ ||
    !std::isfinite(x) || !std::isfinite(baseline)) return false;
for (std::size_t i=0; i<count_; ++i)
    if (!atlas_->contains(items_[i].region)) return false;

study_atlas::GlyphAtlas atlas(gl,256,256);
study_text::AtlasLine menu_text,play_text;
study_image_quad::ImageQuad text_quad(gl);
if (!atlas.init() ||
    !text_quad.init(study_image_quad::Sampling::coverage) ||
    !menu_text.init(atlas,*menu_pixels) ||
    !play_text.init(atlas,*play_label_pixels)) return 1;
